# Change a claim's status (open, settle, approve, reject, void, resettle, delete or restore). A DRAFT claim is deleted (DELETED, counted nowhere) and restored to a DRAFT only on the sheet-today it was deleted. A clerk's settle above the clerk limit leaves it PENDING for a steward to approve or reject. A steward's resettle freezes a SETTLED claim again at today's figure; a steward may void a SETTLED claim within 7 days of its settlement, its frozen figure leaving every total. A refused change (not allowed from the claim's status or by this user, unknown claim, a claim dated in a closed period, an open past its period's cap on the person's OPEN or PENDING claims, a void without a reason from the sheet's list while it has any) writes nothing, not even an audit line.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimStatus
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
closed:
  class: net.officefloor.hq.app.period.RefuseClosedClaim
  govern: [ transaction ]
  next: capped
capped:
  class: net.officefloor.hq.app.period.RefuseCappedOpen
  govern: [ transaction ]
  next: reason
reason:
  class: net.officefloor.hq.app.claim.RefuseVoidWithoutReason
  govern: [ transaction ]
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimStatus
  govern: [ transaction ]
  next: voided
voided:
  class: net.officefloor.hq.app.claim.SaveClaimVoidReason
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimStatus
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.AuditClaimStatusRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# Open the selected claims together, in list order. Each that can be opened is opened (numbered, audited and
# rolled up as a single open is); each that cannot is left as it is. Responds with how many of each.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkOpen
  next: open
open:
  class: net.officefloor.hq.app.claim.BulkOpenClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkOpen
