            if (closed != null) {
                throw new InvalidClaimException("Line " + line.number() + ": " + new ClosedPeriodException(closed).getMessage());
            }
            owners.add(person);
        }
        for (int i = 0; i < owners.size(); i++) {
            ClaimInput claim = input.lines().get(i).claim();
            Person person = owners.get(i);
