package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Apply the edit to the loaded claim and store it; a cleared date becomes the sheet's today. */
public class SaveClaim {
    public void save(@Val ClaimInput input, @Val Claim loaded, SheetRepository sheets, ClaimRepository repository,
            Out<ClaimResponse> saved) {
        var date = input.date() != null ? input.date() : sheets.today(loaded.sheetId());
        Claim claim = new Claim(loaded.id(), loaded.sheetId(), loaded.personId(), input.amount(), date, input.note(),
                loaded.status(), loaded.number(), loaded.settledDue(), loaded.openedBy(),
                loaded.stated(), loaded.statedDue(), input.corrects(), loaded.dueBy(), loaded.deferredUntil(),
                loaded.proofs(), loaded.splitFrom(), loaded.lateEntry(), loaded.reminded(), input.ref(),
                input.tags() == null ? loaded.tags() : input.tags().isEmpty() ? null : input.tags());
        repository.update(claim, input.user());
        saved.set(ClaimResponse.from(claim));
    }
}
package net.officefloor.hq.app.claim;


/** Refuse an edit of a claim whose editor another user holds open (locked). */
public class RefuseLockedClaimEdit {
    public void refuse(@Val ClaimInput input, @Val Claim loaded, ClaimRepository repository)
            throws ClaimStatusNotAllowedException {
        String holder = repository.lockedBy(loaded);
        if (holder != null && !holder.equals(input.user())) {
            throw new ClaimStatusNotAllowedException("This claim is being edited by " + holder
                    + "; it cannot be edited until they save or cancel.");
        }
    }
}
package net.officefloor.hq.app.claim;


/** Refuse an edit typing an amount other than the lines' total on a claim with lines: its amount is their total. */
public class RefuseLinedAmountEdit {
    public void refuse(@Val ClaimInput input, @Val Claim loaded, ClaimLineRepository lines)
            throws InvalidClaimException {
        var total = lines.total(loaded);
        if (total != null && total.compareTo(input.amount()) != 0) {
            throw new InvalidClaimException("This claim has lines; its amount is their total, "
                    + total.toPlainString() + ", and cannot be typed.");
        }
    }
}

